_ALIASES = {
    "confidence": "chart-no-axes",
    "monitoring": "package-search",
    "refresh": "refresh-cw",
    "clock-3": "clock",
    "split": "git-branch",
    "stock": "boxes",
    "pricing": "dollar-sign",
    "lifecycle": "clock",
    "inventory": "package-search",
    "reports": "file-text",
    "exports": "file-spreadsheet",
    "downloads": "download",
    "approved": "badge-check",
    "rejected": "circle-x",
    "pending-reviews": "clipboard-check",
}


def resolve_icon(name: str) -> str:
    key = str(name or "").strip().lower()
    if key in _ALIASES:
        key = _ALIASES[key]
    return key if key in _ICONS else ""


def lucide(name: str, size: int = 18) -> str:
    key = resolve_icon(name)
    if not key:
        return ""
    return _ICONS[key].format(s=size)


def icon_or_empty(name: str, size: int = 18) -> str:
    markup = lucide(name, size)
    if not markup:
        return ""
    return f'<span class="cv64-icon" aria-hidden="true">{markup}</span>'
